import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
export function relocate(html,expected={preloads:11,styles:1,imports:2}){
 if(/integrity=|content-security-policy|nonce=/i.test(html))throw Error('CSP/SRI requires separate reviewed generation');
 const scripts=[...html.matchAll(/<script>([\s\S]*?)<\/script>/g)];
 if(scripts.length!==1||!scripts[0][1].includes('kit.start(app, element);')||!scripts[0][1].includes("base: new URL('.', location).pathname.slice(0, -1)"))throw Error('unknown Kit bootstrap');
 const seen={preloads:0,styles:0,imports:0};let output=html.replace(/<link href="(\.?\/_app\/immutable\/[A-Za-z0-9_./-]+)" rel="(modulepreload|stylesheet)">/g,(_,url,rel)=>{seen[rel==='stylesheet'?'styles':'preloads']++;return `<link href="${url.startsWith('.')?url:'.'+url}" rel="${rel}">`;});
 const raw=scripts[0][0];const patched=raw.replace(/import\("(\.?\/_app\/immutable\/entry\/(?:start|app)\.[A-Za-z0-9_-]+\.js)"\)/g,(_,url)=>{seen.imports++;return `import("${url.startsWith('.')?url:'.'+url}")`;});
 output=output.replace(raw,patched);
 assert.deepEqual(seen,expected,'generated reference count drift');
 if(/(?<!\.)\/_app\//.test(output))throw Error('unrecognised absolute app reference');
 return {html:output,counts:seen};
}
const path=process.argv[2];
if(path){const original=await readFile(path,'utf8');const out=relocate(original);assert.equal(relocate(out.html).html,out.html,'not idempotent');for(const bad of [original.replace('rel="modulepreload"','rel="x"'),original.replace('kit.start(app, element);','kit.changed();'),original.replace('</head>','<script>"/_app/user-string"</script></head>'),original.replace('<script>','<script nonce="x">')])assert.throws(()=>relocate(bad));await writeFile(path+'.original',original);await writeFile(path,out.html);await writeFile('relocation.json',JSON.stringify({kit:'3.0.0',adapter:'4.0.0',...out,html:undefined,originalSha256:createHash('sha256').update(original).digest('hex'),resultSha256:createHash('sha256').update(out.html).digest('hex'),idempotent:true,negativeCases:4},null,2)+'\n');}

