async function raw(dir){let n=0;for(const e of await readdir(dir,{withFileTypes:true})){if(e.name.endsWith('.original'))continue;const p=resolve(dir,e.name);n+=e.isDirectory()?await raw(p):(await stat(p)).size;}return n;}
const server=createServer(async(req,res)=>{const u=new URL(req.url,'http://fixture');const record={method:req.method,path:u.pathname.includes(token)?'redacted':u.pathname,secretInRequest:req.url.includes(token),status:404,bytes:0};records.push(record);if(!u.pathname.startsWith(base)){res.writeHead(404);res.end();return;}const p=u.pathname.slice(base.length)||'index.html';try{if(p.includes('..')||p.endsWith('.original'))throw Error();if(versionFail&&p==='_app/version.json'){record.status=503;res.writeHead(503);res.end();return;}const b=await readFile(resolve(folder,p));Object.assign(record,{status:200,bytes:b.length,sha256:digest(b)});res.writeHead(200,{'content-type':{'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.woff2':'font/woff2'}[extname(p)]??'application/octet-stream','content-length':b.length,'cache-control':'no-store'});res.end(b);}catch{res.writeHead(404);res.end();}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;
