t(300);row.version={requests:records.slice(start).filter(r=>r.path.includes('version')),navigations};const leaks=[];for(const [hash,heading] of [['#g='+token+'&n=guest','게스트 proof'],['#/join?room=fixture&t='+token,'참여 proof']]){await page.goto(origin+base+hash);await page.getByRole('heading',{name:heading}).waitFor();const data=await page.evaluate(t=>({history:JSON.stringify(history.state).includes(t),title:document.title.includes(t),text:document.body.innerText.includes(t),announcer:[...document.querySelectorAll('[aria-live]')].some(e=>e.textContent.includes(t)),remoteScrubbed:location.hash==='#/join',nestedTicket:location.hash.startsWith('#/guest#g=')}),token);leaks.push(data);}row.tokens=leaks;}
row.complete=!errors.length&&!outbound.length&&records.every(r=>r.status===200||r.status===503)&&workers.every(p=>p.startsWith(base));}catch(e){row.failure=e.name;row.failureMessage=e.message.replaceAll(token,'<token>').slice(0,500);}finally{Object.assign(row,{errors,outbound,workers,records:[...records]});rows.push(row);await context.close();}}}finally{await browser.close();}}}finally{await new Promise(r=>server.close(r));await writeFile(base==='/'?'matrix-root-results.json':'matrix-results.json',JSON.stringify({rows},null,2)+'\n');}
